import random
from svglib import *


def walk(seed, segs, start=100):
    rnd = random.Random(seed); c = [start]
    for n, drift, vol in segs:
        for _ in range(n): c.append(c[-1] + drift + rnd.gauss(0, vol))
    return c


def bb_fig(closes, label, seed, start=19, x1=560, right=True, extra=None, wick=0.4):
    mid, up, dn = boll(closes)
    K = ohlc(closes, seed=seed, wick=wick)[start:]
    mid, up, dn = mid[start:], up[start:], dn[start:]
    n = len(K)
    lo = min(min(k[2] for k in K), min(dn)); hi = max(max(k[1] for k in K), max(up)); pad = (hi - lo) * 0.07
    P = Panel(20, 24, x1, 356, lo - pad, hi + pad, n)
    o = head(label)
    # fill between bands
    pts = ' '.join(f'{P.X(i):.1f},{P.Y(v):.1f}' for i, v in enumerate(up)) + ' ' + \
          ' '.join(f'{P.X(i):.1f},{P.Y(v):.1f}' for i, v in reversed(list(enumerate(dn))))
    o.append(f'<polygon points="{pts}" fill="{VIOLET}" fill-opacity=".10"/>')
    o.append(P.line(up, VIOLET, 2.2)); o.append(P.line(dn, VIOLET, 2.2)); o.append(P.line(mid, AMBER, 1.8, dash='6 5'))
    o += P.candles(K)
    if right:
        ys = [P.Y(up[-1]), P.Y(mid[-1]), P.Y(dn[-1])]
        # keep labels at least 34px apart
        if ys[1] - ys[0] < 34: ys[0] = ys[1] - 34
        if ys[2] - ys[1] < 34: ys[2] = ys[1] + 34
        o.append(text(x1 + 14, ys[0] + 7, 'верхня', VIOLET if False else MOON, 20))
        o.append(text(x1 + 14, ys[1] + 7, 'SMA 20', AMBER, 20))
        o.append(text(x1 + 14, ys[2] + 7, 'нижня', MOON, 20))
    if extra: o += extra(P, K, mid, up, dn)
    o.append('</svg>')
    return '\n'.join(o)


c1 = walk(8, [(22, 0, 0.6), (12, 0.35, 0.6), (10, -0.45, 0.6), (8, 0.1, 0.6)])
svg1 = bb_fig(c1, 'Смуги Боллінджера: верхня, середня і нижня лінії', 81)

c2 = walk(9, [(20, 0, 0.7), (18, 0, 0.15), (10, 0.9, 0.5), (4, 0.2, 0.4)])
def ex2(P, K, mid, up, dn):
    i0, i1 = 10, 17
    xa, xb = P.X(i0) - P.cw / 2, P.X(i1) + P.cw / 2
    ya, yb = P.Y(max(up[i0:i1 + 1])) - 8, P.Y(min(dn[i0:i1 + 1])) + 8
    return [f'<rect x="{xa:.1f}" y="{ya:.1f}" width="{xb-xa:.1f}" height="{yb-ya:.1f}" rx="8" fill="none" stroke="{AMBER}" stroke-width="1.8" stroke-dasharray="5 4"/>',
            tag((xa + xb) / 2, yb + 30, 'звуження', AMBER, 20, 'middle'),
            tag(P.X(n2 - 9), P.Y(up[n2 - 1]) - 4, 'розширення', MINT, 20, 'end')]
n2 = len(c2) - 21
svg2 = bb_fig(c2, 'Звуження смуг Боллінджера і розширення після нього', 92, start=21, x1=640, right=False, extra=ex2)

c3 = walk(10, [(22, 0, 0.5), (10, 0.5, 0.3), (10, 0.75, 0.3), (8, 0.9, 0.35)])
def ex3(P, K, mid, up, dn):
    return [tag(32, 46, 'ціна йде вздовж', MINT, 20), tag(32, 86, 'верхньої смуги', MINT, 20)]
svg3 = bb_fig(c3, 'Сильний тренд: ціна довго йде вздовж верхньої смуги', 103, extra=ex3)

